 31  type ImportDraft = {
 32    identity: string;
 33    name: string;
 34    effect: "READ" | "WRITE";
 35    risk_level: "LOW" | "MEDIUM" | "HIGH";
 36    approval_policy: "NEVER" | "ALWAYS";
 37    timeout_seconds: string;
 38  };
 39  
 40  function slugify(value: string): string {
 41    const slug = value.toLowerCase().replace(/[^a-z0-9_-]+/g, "_").replace(/^_+|_+$/g, "");
 42    return slug.slice(0, 64);
 43  }
 44  
 45  function defaultDraft(remoteName: string, title: string | null): ImportDraft {
 46    return {
 47      identity: slugify(remoteName),
 48      name: title ?? remoteName,
 49      effect: "READ",
 50      risk_level: "LOW",
 51      approval_policy: "NEVER",
 52      timeout_seconds: "",
 53    };
 54  }
