 56  export default function McpImportPage() {
 57    const { t, statusLabel } = useI18n();
 58    const { workspaceId, accessToken, connected, sessionId } = useFrontendSession();
 59  
 60    const loadConnections = useCallback(
 61      (auth: AuthInput) => listMcpConnections(auth),
 62      [],
 63    );
 64    const connections = useWorkspaceData<McpConnection[]>(
 65      loadConnections,
 66      `mcp-connections:${workspaceId}`,
 67    );
 68    const connectionMutation = useWorkspaceMutation(`mcp-connections:${workspaceId}`);
 69    const [showCreateForm, setShowCreateForm] = useState(false);
 70    const [name, setName] = useState("");
 71    const [endpointUrl, setEndpointUrl] = useState("");
 72    const [authType, setAuthType] = useState<"NONE" | "BEARER">("NONE");
 73    const [secret, setSecret] = useState("");
 74  
 75    const [selectedConnectionId, setSelectedConnectionId] = useState<string | null>(null);
 76    const [testResult, setTestResult] = useState<McpConnectionTest | null>(null);
 77    const [testing, setTesting] = useState(false);
 78    const [discovery, setDiscovery] = useState<McpDiscovery | null>(null);
 79    const [discovering, setDiscovering] = useState(false);
 80    const [actionError, setActionError] = useState<ApiError | null>(null);
 81    const [importDrafts, setImportDrafts] = useState<Record<string, ImportDraft>>({});
 82    const [importedIds, setImportedIds] = useState<Record<string, string>>({});
 83    const importMutation = useWorkspaceMutation(`mcp-import:${workspaceId}`);
 84  
 85    // Another workspace is another set of connections: nothing selected or
 86    // discovered carries over.
 87    useEffect(() => {
 88      setSelectedConnectionId(null);
 89      setTestResult(null);
 90      setDiscovery(null);
 91      setImportDrafts({});
 92      setImportedIds({});
 93    }, [sessionId, workspaceId]);
 94  
 95    const connectionList = connections.data ?? [];
 96    const selectedConnection =
 97      connectionList.find((item) => item.id === selectedConnectionId) ?? null;
 98  
 99    async function submitConnection(event: FormEvent<HTMLFormElement>) {
100      event.preventDefault();
101      const result = await connectionMutation.run((auth) =>
102        createMcpConnection(auth, {
103          name: name.trim(),
104          endpoint_url: endpointUrl.trim(),
105          auth_type: authType,
106          ...(authType === "BEARER" && secret ? { secret } : {}),
107        }),
108      );
109      if (result) {
110        setName("");
111        setEndpointUrl("");
112        setSecret("");
113        setAuthType("NONE");
114        setShowCreateForm(false);
115        connections.reload();
116      }
117    }
118  
119    async function runTest(connectionId: string) {
120      setTesting(true);
121      setActionError(null);
122      setTestResult(null);
123      try {
124        const result = await testMcpConnection({ workspaceId, accessToken }, connectionId);
125        setTestResult(result);
126      } catch (caught) {
127        setActionError(toApiError(caught, ""));
128      } finally {
129        setTesting(false);
130      }
131    }
132  
133    async function runDiscovery(connectionId: string) {
134      setDiscovering(true);
135      setActionError(null);
136      setDiscovery(null);
137      setImportDrafts({});
138      setImportedIds({});
139      try {
140        const result = await discoverMcpTools({ workspaceId, accessToken }, connectionId);
141        setDiscovery(result);
142      } catch (caught) {
143        setActionError(toApiError(caught, ""));
144      } finally {
145        setDiscovering(false);
146      }
147    }
148  
149    async function submitImport(remoteToolName: string) {
150      const draft = importDrafts[remoteToolName];
151      if (!draft || !selectedConnectionId) return;
152      const result = await importMutation.run((auth) =>
153        importMcpTool(auth, selectedConnectionId, {
154          remote_tool_name: remoteToolName,
155          identity: draft.identity.trim(),
156          name: draft.name.trim() || null,
157          effect: draft.effect,
158          risk_level: draft.risk_level,
159          approval_policy: draft.approval_policy,
160          timeout_seconds: draft.timeout_seconds ? Number(draft.timeout_seconds) : null,
161        }),
162      );
163      if (result) {
164        setImportedIds((current) => ({ ...current, [remoteToolName]: result.id }));
165      }
166    }
